__all__ = ["AsyncHttpClient", "HttpClient", "WORKSPACE_ID_ERROR", "WORKSPACE_ID_PATTERN"]

#: Headers the SDK never sends: the API derives tenancy from the token and workspace_id.
_TENANCY_HEADERS = frozenset({"x-organization-id", "x-workspace-id", "x-project-id"})


def _validate_workspace_id(params: typing.Dict[str, typing.Any]) -> None:
    """Validate (and normalise to ``str``) the single ``workspace_id`` query parameter in place."""
    params["workspace_id"] = validate_workspace_id(params.get("workspace_id"))


def _merged_query(
    params: typing.Optional[typing.Dict[str, typing.Any]], request_options: typing.Optional[RequestOptions]
) -> typing.Dict[str, typing.Any]:
    return {
        **(params if params is not None else {}),
        **(request_options.get("additional_query_parameters", {}) or {} if request_options is not None else {}),
    }


def _header_lookup(headers: typing.Mapping[str, typing.Any], name: str) -> typing.Optional[str]:
    lowered = name.lower()
    for key, value in headers.items():
        if key.lower() == lowered and value is not None:
            return str(value)
    return None


def _set_header(headers: typing.Dict[str, typing.Any], name: str, value: str) -> None:
    lowered = name.lower()
    for key in [key for key in headers if key.lower() == lowered]:
        del headers[key]
    headers[name] = value


def _response_body(response: httpx.Response) -> typing.Any:
    try:
        return response.json()
    except Exception:
        return response.text


def _raise_for_error_response(
    response: httpx.Response, *, path: typing.Optional[str], idempotency_key: typing.Optional[str]
) -> None:
    if response.status_code < 400:
        return
    from ..errors.factory import error_from_response

    raise error_from_response(
        response.status_code,
        _response_body(response),
        dict(response.headers),
        idempotency_key,
        path=path,
    )


def _attach_idempotency_key(error: BaseException, key: typing.Optional[str]) -> None:
    if key is None:
        return
    try:
        setattr(error, "idempotency_key", key)
    except Exception:  # pragma: no cover - exotic exception types
        pass


class _PreparedRequest(typing.NamedTuple):
    url: str
    headers: typing.Dict[str, typing.Any]
    params: typing.Any
    json_body: typing.Any
    data_body: typing.Any
    files: typing.Optional[RequestFiles]
    timeout: typing.Any
    retry_safe: bool
    idempotency_key: typing.Optional[str]
    max_retries: int


def _prepare_request(
    *,
    path: typing.Optional[str],
    method: str,
    base_url: str,
    base_headers: typing.Dict[str, str],
    default_timeout: typing.Optional[float],
    default_max_retries: int,
    params: typing.Optional[typing.Dict[str, typing.Any]],
    json: typing.Optional[typing.Any],
    data: typing.Optional[typing.Any],
    content: typing.Any,
    files: typing.Any,
    headers: typing.Optional[typing.Dict[str, typing.Any]],
    request_options: typing.Optional[RequestOptions],
    omit: typing.Optional[typing.Any],
    force_multipart: typing.Optional[bool],
) -> _PreparedRequest:
    _timeout = (
        request_options.get("timeout_in_seconds")
        if request_options is not None and request_options.get("timeout_in_seconds") is not None
        else default_timeout
    )
    timeout = _timeout if _timeout is not None else httpx.USE_CLIENT_DEFAULT

    json_body, data_body = get_request_body(json=json, data=data, request_options=request_options, omit=omit)

    request_files: typing.Optional[RequestFiles] = (
        convert_file_dict_to_httpx_tuples(remove_omit_from_dict(remove_none_from_dict(files), omit))
        if (files is not None and files is not omit and isinstance(files, dict))
        else None
    )

    if (request_files is None or len(request_files) == 0) and force_multipart:
        request_files = FORCE_MULTIPART

    data_body = _maybe_filter_none_from_multipart_data(data_body, request_files, force_multipart)

    # Compute encoded params separately to avoid passing empty list to httpx
    # (httpx strips existing query params from URL when params=[] is passed)
    _query_params = _merged_query(params, request_options)
    _validate_workspace_id(_query_params)
    _query_params = remove_none_from_dict(remove_omit_from_dict(_query_params, omit))
    _encoded_params = encode_query(jsonable_encoder(_query_params))

    _request_headers = jsonable_encoder(
        remove_none_from_dict(
            {
                **base_headers,
                **(headers if headers is not None else {}),
                **(request_options.get("additional_headers", {}) or {} if request_options is not None else {}),
            }
        )
    )
    for key in [key for key in _request_headers if key.lower() in _TENANCY_HEADERS]:
        del _request_headers[key]

    # Billable creates: always a JSON object body, at most 64 KiB.
    if (
        is_billable_create(method, path)
        and json_body is None
        and data_body is None
        and content is None
        and not request_files
    ):
        json_body = {}
    check_billable_body_size(method, path, json_body)

    # Cloud/GPU VM writes: validate a caller key, or generate one once per logical call.
    ve_scope = ve_auto_key_scope(method, path, json_body)
    if ve_scope is not None:
        supplied = _header_lookup(_request_headers, IDEMPOTENCY_HEADER)
        if supplied is None or not supplied.strip():
            key = build_idempotency_key(ve_scope[0], ve_scope[1])
        else:
            key = validate_idempotency_key(supplied)
        _set_header(_request_headers, IDEMPOTENCY_HEADER, key)

    retry_safe = is_retry_safe(method, path, _request_headers, json_body, _query_params)
    idempotency_key = any_idempotency_key(_request_headers, json_body, _query_params)

    max_retries: int = (
        request_options.get("max_retries", default_max_retries) if request_options is not None else default_max_retries
    )

    return _PreparedRequest(
        url=_build_url(base_url, path),
        headers=_request_headers,
        params=_encoded_params if _encoded_params else None,
        json_body=json_body,
        data_body=data_body,
        files=request_files,
        timeout=timeout,
        retry_safe=retry_safe,
        idempotency_key=idempotency_key,
        max_retries=max_retries if max_retries is not None else default_max_retries,
    )


_SENSITIVE_HEADERS = frozenset(
    {
        "authorization",
        "www-authenticate",
        "x-api-key",
        "api-key",
        "apikey",
        "x-api-token",
        "x-auth-token",
        "auth-token",
        "cookie",
        "set-cookie",
        "proxy-authorization",
        "proxy-authenticate",
        "x-csrf-token",
        "x-xsrf-token",
        "x-session-token",
        "x-access-token",
    }
)


def _redact_headers(headers: typing.Dict[str, str]) -> typing.Dict[str, str]:
    return {k: ("[REDACTED]" if k.lower() in _SENSITIVE_HEADERS else v) for k, v in headers.items()}


def _build_url(base_url: str, path: typing.Optional[str]) -> str:
    """
    Build a full URL by joining a base URL with a path.

    This function correctly handles base URLs that contain path prefixes (e.g., tenant-based URLs)
    by using string concatenation instead of urllib.parse.urljoin(), which would incorrectly
    strip path components when the path starts with '/'.

    Example:
        >>> _build_url("https://cloud.example.com/org/tenant/api", "/users")
        'https://cloud.example.com/org/tenant/api/users'

    Args:
        base_url: The base URL, which may contain path prefixes.
        path: The path to append. Can be None or empty string.

    Returns:
        The full URL with base_url and path properly joined.
    """
    if not path:
        return base_url
    return f"{base_url.rstrip('/')}/{path.lstrip('/')}"


def _maybe_filter_none_from_multipart_data(
    data: typing.Optional[typing.Any],
    request_files: typing.Optional[RequestFiles],
    force_multipart: typing.Optional[bool],
) -> typing.Optional[typing.Any]:
    """
    Filter None values from data body for multipart/form requests.
    This prevents httpx from converting None to empty strings in multipart encoding.
    Only applies when files are present or force_multipart is True.
    """
    if data is not None and isinstance(data, typing.Mapping) and (request_files or force_multipart):
        return remove_none_from_dict(data)
    return data


def remove_omit_from_dict(
    original: typing.Dict[str, typing.Optional[typing.Any]],
    omit: typing.Optional[typing.Any],
) -> typing.Dict[str, typing.Any]:
    if omit is None:
        return original
    new: typing.Dict[str, typing.Any] = {}
    for key, value in original.items():
        if value is not omit:
            new[key] = value
    return new


def maybe_filter_request_body(
    data: typing.Optional[typing.Any],
    request_options: typing.Optional[RequestOptions],
    omit: typing.Optional[typing.Any],
) -> typing.Optional[typing.Any]:
    if data is None:
        return (
            jsonable_encoder(request_options.get("additional_body_parameters", {})) or {}
            if request_options is not None
            else None
        )
    elif not isinstance(data, typing.Mapping):
        data_content = jsonable_encoder(data)
    else:
        data_content = {
            **(jsonable_encoder(remove_omit_from_dict(data, omit))),  # type: ignore
            **(
                jsonable_encoder(request_options.get("additional_body_parameters", {})) or {}
                if request_options is not None
                else {}
            ),
        }
    return data_content


# Abstracted out for testing purposes
def get_request_body(
    *,
    json: typing.Optional[typing.Any],
    data: typing.Optional[typing.Any],
    request_options: typing.Optional[RequestOptions],
    omit: typing.Optional[typing.Any],
) -> typing.Tuple[typing.Optional[typing.Any], typing.Optional[typing.Any]]:
    json_body = None
    data_body = None
    if data is not None:
        data_body = maybe_filter_request_body(data, request_options, omit)
    else:
        # If both data and json are None, we send json data in the event extra properties are specified
        json_body = maybe_filter_request_body(json, request_options, omit)

    has_additional_body_parameters = bool(
        request_options is not None and request_options.get("additional_body_parameters")
    )

    # Only collapse empty dict to None when the body was not explicitly provided
    # and there are no additional body parameters. This preserves explicit empty
    # bodies (e.g., when an endpoint has a request body type but all fields are optional).
    if json_body == {} and json is None and not has_additional_body_parameters:
        json_body = None
    if data_body == {} and data is None and not has_additional_body_parameters:
        data_body = None

    return json_body, data_body


class HttpClient:
    def __init__(
        self,
        *,
        httpx_client: httpx.Client,
        base_timeout: typing.Callable[[], typing.Optional[float]],
        base_headers: typing.Callable[[], typing.Dict[str, str]],
        base_url: typing.Optional[typing.Callable[[], str]] = None,
        base_max_retries: int = 2,
        logging_config: typing.Optional[typing.Union[LogConfig, Logger]] = None,
    ):
        self.base_url = base_url
        self.base_timeout = base_timeout
        self.base_headers = base_headers
        self.base_max_retries = base_max_retries
        self.httpx_client = httpx_client
        self.logger = create_logger(logging_config)

    def get_base_url(self, maybe_base_url: typing.Optional[str]) -> str:
        base_url = maybe_base_url
        if self.base_url is not None and base_url is None:
            base_url = self.base_url()

        if base_url is None:
            raise ValueError("A base_url is required to make this request, please provide one and try again.")
        return base_url

    def request(
        self,
        path: typing.Optional[str] = None,
        *,
        method: str,
        base_url: typing.Optional[str] = None,
        params: typing.Optional[typing.Dict[str, typing.Any]] = None,
        json: typing.Optional[typing.Any] = None,
        data: typing.Optional[typing.Any] = None,
        content: typing.Optional[typing.Union[bytes, typing.Iterator[bytes], typing.AsyncIterator[bytes]]] = None,
        files: typing.Optional[
            typing.Union[
                typing.Dict[str, typing.Optional[typing.Union[File, typing.List[File]]]],
                typing.List[typing.Tuple[str, File]],
            ]
        ] = None,
        headers: typing.Optional[typing.Dict[str, typing.Any]] = None,
        request_options: typing.Optional[RequestOptions] = None,
        retries: int = 0,
        omit: typing.Optional[typing.Any] = None,
        force_multipart: typing.Optional[bool] = None,
    ) -> httpx.Response:
        """Send a request, retrying only when safe; raise a typed ``ApiError`` for status >= 400."""
        base_url_value = self.get_base_url(base_url)
        _validate_workspace_id(_merged_query(params, request_options))
        prepared = _prepare_request(
            path=path,
            method=method,
            base_url=base_url_value,
            base_headers=self.base_headers(),
            default_timeout=self.base_timeout(),
            default_max_retries=self.base_max_retries,
            params=params,
            json=json,
            data=data,
            content=content,
            files=files,
            headers=headers,
            request_options=request_options,
            omit=omit,
            force_multipart=force_multipart,
        )

        if self.logger.is_debug():
            self.logger.debug(
                "Making HTTP request",
                method=method,
                url=prepared.url,
                headers=_redact_headers(prepared.headers),
                has_body=prepared.json_body is not None or prepared.data_body is not None,
            )

        attempt = retries
        while True:
            try:
                response = self.httpx_client.request(
                    method=method,
                    url=prepared.url,
                    headers=prepared.headers,
                    params=prepared.params,
                    json=prepared.json_body,
                    data=prepared.data_body,
                    content=content,
                    files=prepared.files,
                    timeout=prepared.timeout,
                )
            except httpx.TransportError as exc:
                if attempt < prepared.max_retries and is_retryable_transport_error(
                    exc, retry_safe=prepared.retry_safe
                ):
                    time.sleep(retry_delay(attempt))
                    attempt += 1
                    continue
                _attach_idempotency_key(exc, prepared.idempotency_key)
                raise
            if prepared.retry_safe and should_retry_status(response.status_code) and attempt < prepared.max_retries:
                time.sleep(retry_delay(attempt, response.headers))
                attempt += 1
                continue
            break

        if self.logger.is_debug():
            if 200 <= response.status_code < 400:
                self.logger.debug(
                    "HTTP request succeeded",
                    method=method,
                    url=prepared.url,
                    status_code=response.status_code,
                )

        if self.logger.is_error():
            if response.status_code >= 400:
                self.logger.error(
                    "HTTP request failed with error status",
                    method=method,
                    url=prepared.url,
                    status_code=response.status_code,
                )

        _raise_for_error_response(response, path=path, idempotency_key=prepared.idempotency_key)
        return response

    @contextmanager
    def stream(
        self,
        path: typing.Optional[str] = None,
        *,
        method: str,
        base_url: typing.Optional[str] = None,
        params: typing.Optional[typing.Dict[str, typing.Any]] = None,
        json: typing.Optional[typing.Any] = None,
        data: typing.Optional[typing.Any] = None,
        content: typing.Optional[typing.Union[bytes, typing.Iterator[bytes], typing.AsyncIterator[bytes]]] = None,
        files: typing.Optional[
            typing.Union[
                typing.Dict[str, typing.Optional[typing.Union[File, typing.List[File]]]],
                typing.List[typing.Tuple[str, File]],
            ]
        ] = None,
        headers: typing.Optional[typing.Dict[str, typing.Any]] = None,
        request_options: typing.Optional[RequestOptions] = None,
        retries: int = 0,
        omit: typing.Optional[typing.Any] = None,
        force_multipart: typing.Optional[bool] = None,
    ) -> typing.Iterator[httpx.Response]:
        prepared = _prepare_request(
            path=path,
            method=method,
            base_url=self.get_base_url(base_url),
            base_headers=self.base_headers(),
            default_timeout=self.base_timeout(),
            default_max_retries=self.base_max_retries,
            params=params,
            json=json,
            data=data,
            content=content,
            files=files,
            headers=headers,
            request_options=request_options,
            omit=omit,
            force_multipart=force_multipart,
        )

        if self.logger.is_debug():
            self.logger.debug(
                "Making streaming HTTP request",
                method=method,
                url=prepared.url,
                headers=_redact_headers(prepared.headers),
            )

        with self.httpx_client.stream(
            method=method,
            url=prepared.url,
            headers=prepared.headers,
            params=prepared.params,
            json=prepared.json_body,
            data=prepared.data_body,
            content=content,
            files=prepared.files,
            timeout=prepared.timeout,
        ) as stream:
            if stream.status_code >= 400:
                stream.read()
                _raise_for_error_response(stream, path=path, idempotency_key=prepared.idempotency_key)
            yield stream


class AsyncHttpClient:
    def __init__(
        self,
        *,
        httpx_client: httpx.AsyncClient,
        base_timeout: typing.Callable[[], typing.Optional[float]],
        base_headers: typing.Callable[[], typing.Dict[str, str]],
        base_url: typing.Optional[typing.Callable[[], str]] = None,
        base_max_retries: int = 2,
        async_base_headers: typing.Optional[typing.Callable[[], typing.Awaitable[typing.Dict[str, str]]]] = None,
        logging_config: typing.Optional[typing.Union[LogConfig, Logger]] = None,
    ):
        self.base_url = base_url
        self.base_timeout = base_timeout
        self.base_headers = base_headers
        self.base_max_retries = base_max_retries
        self.async_base_headers = async_base_headers
        self.httpx_client = httpx_client
        self.logger = create_logger(logging_config)

    async def _get_headers(self) -> typing.Dict[str, str]:
        if self.async_base_headers is not None:
            return await self.async_base_headers()
        return self.base_headers()

    def get_base_url(self, maybe_base_url: typing.Optional[str]) -> str:
        base_url = maybe_base_url
        if self.base_url is not None and base_url is None:
            base_url = self.base_url()

        if base_url is None:
            raise ValueError("A base_url is required to make this request, please provide one and try again.")
        return base_url

    async def request(
        self,
        path: typing.Optional[str] = None,
        *,
        method: str,
        base_url: typing.Optional[str] = None,
        params: typing.Optional[typing.Dict[str, typing.Any]] = None,
        json: typing.Optional[typing.Any] = None,
        data: typing.Optional[typing.Any] = None,
        content: typing.Optional[typing.Union[bytes, typing.Iterator[bytes], typing.AsyncIterator[bytes]]] = None,
        files: typing.Optional[
            typing.Union[
                typing.Dict[str, typing.Optional[typing.Union[File, typing.List[File]]]],
                typing.List[typing.Tuple[str, File]],
            ]
        ] = None,
        headers: typing.Optional[typing.Dict[str, typing.Any]] = None,
        request_options: typing.Optional[RequestOptions] = None,
        retries: int = 0,
        omit: typing.Optional[typing.Any] = None,
        force_multipart: typing.Optional[bool] = None,
    ) -> httpx.Response:
        """Send a request, retrying only when safe; raise a typed ``ApiError`` for status >= 400."""
        # Validate the request before resolving (possibly async) credentials.
        base_url_value = self.get_base_url(base_url)
        _validate_workspace_id(_merged_query(params, request_options))
        prepared = _prepare_request(
            path=path,
            method=method,
            base_url=base_url_value,
            base_headers=await self._get_headers(),
            default_timeout=self.base_timeout(),
            default_max_retries=self.base_max_retries,
            params=params,
            json=json,
            data=data,
            content=content,
            files=files,
            headers=headers,
            request_options=request_options,
            omit=omit,
            force_multipart=force_multipart,
        )

        if self.logger.is_debug():
            self.logger.debug(
                "Making HTTP request",
                method=method,
                url=prepared.url,
                headers=_redact_headers(prepared.headers),
                has_body=prepared.json_body is not None or prepared.data_body is not None,
            )

        attempt = retries
        while True:
            try:
                response = await self.httpx_client.request(
                    method=method,
                    url=prepared.url,
                    headers=prepared.headers,
                    params=prepared.params,
                    json=prepared.json_body,
                    data=prepared.data_body,
                    content=content,
                    files=prepared.files,
                    timeout=prepared.timeout,
                )
            except httpx.TransportError as exc:
                if attempt < prepared.max_retries and is_retryable_transport_error(
                    exc, retry_safe=prepared.retry_safe
                ):
                    await asyncio.sleep(retry_delay(attempt))
                    attempt += 1
                    continue
                _attach_idempotency_key(exc, prepared.idempotency_key)
                raise
            if prepared.retry_safe and should_retry_status(response.status_code) and attempt < prepared.max_retries:
                await asyncio.sleep(retry_delay(attempt, response.headers))
                attempt += 1
                continue
            break

        if self.logger.is_debug():
            if 200 <= response.status_code < 400:
                self.logger.debug(
                    "HTTP request succeeded",
                    method=method,
                    url=prepared.url,
                    status_code=response.status_code,
                )

        if self.logger.is_error():
            if response.status_code >= 400:
                self.logger.error(
                    "HTTP request failed with error status",
                    method=method,
                    url=prepared.url,
                    status_code=response.status_code,
                )

        _raise_for_error_response(response, path=path, idempotency_key=prepared.idempotency_key)
        return response

    @asynccontextmanager
    async def stream(
        self,
        path: typing.Optional[str] = None,
        *,
        method: str,
        base_url: typing.Optional[str] = None,
        params: typing.Optional[typing.Dict[str, typing.Any]] = None,
        json: typing.Optional[typing.Any] = None,
        data: typing.Optional[typing.Any] = None,
        content: typing.Optional[typing.Union[bytes, typing.Iterator[bytes], typing.AsyncIterator[bytes]]] = None,
        files: typing.Optional[
            typing.Union[
                typing.Dict[str, typing.Optional[typing.Union[File, typing.List[File]]]],
                typing.List[typing.Tuple[str, File]],
            ]
        ] = None,
        headers: typing.Optional[typing.Dict[str, typing.Any]] = None,
        request_options: typing.Optional[RequestOptions] = None,
        retries: int = 0,
        omit: typing.Optional[typing.Any] = None,
        force_multipart: typing.Optional[bool] = None,
    ) -> typing.AsyncIterator[httpx.Response]:
        prepared = _prepare_request(
            path=path,
            method=method,
            base_url=self.get_base_url(base_url),
            base_headers=await self._get_headers(),
            default_timeout=self.base_timeout(),
            default_max_retries=self.base_max_retries,
            params=params,
            json=json,
            data=data,
            content=content,
            files=files,
            headers=headers,
            request_options=request_options,
            omit=omit,
            force_multipart=force_multipart,
        )

        if self.logger.is_debug():
            self.logger.debug(
                "Making streaming HTTP request",
                method=method,
                url=prepared.url,
                headers=_redact_headers(prepared.headers),
            )

        async with self.httpx_client.stream(
            method=method,
            url=prepared.url,
            headers=prepared.headers,
            params=prepared.params,
            json=prepared.json_body,
            data=prepared.data_body,
            content=content,
            files=prepared.files,
            timeout=prepared.timeout,
        ) as stream:
            if stream.status_code >= 400:
                await stream.aread()
                _raise_for_error_response(stream, path=path, idempotency_key=prepared.idempotency_key)
            yield stream
